{
  "avaliacoes": [
    {
      "id": "E77a0e74615e3e9dd",
      "pertinente": true,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "Os nós de medição são descritos como equipamentos e sistemas que devem ser projetados, instalados, operados, testados e mantidos em condições adequadas para medir a produção de petróleo e gás natural.",
          "trechos": [
            "E77a0e74615e3e9dd:0:693"
          ],
          "condicoes": [
            "aplica-se aos nós de medição na produção de petróleo e gás natural"
          ],
          "limites": [
            "o trecho não detalha critérios de seleção de medidor, condicionamento do escoamento, trechos retos nem limites operacionais"
          ]
        },
        {
          "proposicao": "Há distinção operacional entre medição fiscal em linha, medição fiscal compartilhada e medição fiscal durante o alívio, associadas a diferentes arranjos de instalação e momento de medição.",
          "trechos": [
            "E77a0e74615e3e9dd:693:1383",
            "E77a0e74615e3e9dd:1383:2083"
          ],
          "condicoes": [
            "medição fiscal em linha é descrita a montante do tanque de estocagem de óleo",
            "medição fiscal compartilhada ocorre a jusante do ponto de mistura de óleos de dois ou mais campos",
            "medição durante o alívio ocorre no momento do alívio"
          ],
          "limites": [
            "o texto traz exemplos de arranjos encontrados em ativos específicos, sem estabelecer regra universal de projeto",
            "não informa requisitos geométricos de instalação nem compatibilidade entre tipos de medidor e escoamento"
          ]
        },
        {
          "proposicao": "A medição para apropriação é apresentada como destinada a determinar volumes a serem atribuídos a cada campo em medição compartilhada ou a cada poço em um campo.",
          "trechos": [
            "E77a0e74615e3e9dd:1383:2083"
          ],
          "condicoes": [
            "uso em conjunto de campos com medição compartilhada ou em apropriação por poço"
          ],
          "limites": [
            "não trata de seleção, instalação física nem limites de medidores"
          ]
        }
      ]
    },
    {
      "id": "E48fe760f8a40f292",
      "pertinente": true,
      "tipo": "indeterminado",
      "achados": [
        {
          "proposicao": "O trecho associa a regulação brasileira de medição de óleo e gás à integridade do cálculo de royalties e tributos e indica três tipos de medição regulados: fiscal, transferência de custódia e apropriação da produção.",
          "trechos": [
            "E48fe760f8a40f292:690:1389",
            "E48fe760f8a40f292:1389:2079"
          ],
          "condicoes": [
            "contexto apresentado como atuação regulatória da ANP e do INMETRO no Brasil"
          ],
          "limites": [
            "por ser resumo em fonte secundária e com números suprimidos, não permite recuperar requisitos completos nem limites metrológicos exatos"
          ]
        },
        {
          "proposicao": "A aplicabilidade de medidores multifásicos é descrita como inadequada, naquele contexto, para medição fiscal e de transferência de custódia devido à incerteza relativamente alta, sendo admitida para apropriação da produção.",
          "trechos": [
            "E48fe760f8a40f292:1389:2079"
          ],
          "condicoes": [
            "comparação feita com medição fiscal e de transferência de custódia",
            "referida ao uso de MPFM no contexto regulatório brasileiro descrito no trecho"
          ],
          "limites": [
            "o texto não informa classes de incerteza completas porque os números foram apagados",
            "não detalha critérios de instalação, condicionamento do escoamento ou trechos retos para MPFM"
          ]
        },
        {
          "proposicao": "O cenário descrito para MPFM submarino indica possibilidade de redundância e verificação subsea por instalação adicional no manifold, com aumento de custo e sem necessidade de shut-in em certas verificações.",
          "trechos": [
            "E48fe760f8a40f292:0:690"
          ],
          "condicoes": [
            "relacionado a um cenário específico de arquitetura com medidor adicional no manifold"
          ],
          "limites": [
            "resultado de avaliação de cenário, não requisito geral",
            "fora do foco principal de FPSO/FSO de superfície se tomado isoladamente"
          ]
        }
      ]
    },
    {
      "id": "E5f17fede420eb30f",
      "pertinente": true,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "A medição operacional é apresentada como voltada ao controle da produção e inclui diversas correntes e usos internos do campo, distinguindo-se da medição fiscal e da transferência de custódia.",
          "trechos": [
            "E5f17fede420eb30f:0:688"
          ],
          "condicoes": [
            "abrange petróleo, gás natural, água produzida e correntes destinadas a combustível, elevação artificial, injeção, estocagem, ventilação, queima em tocha, processamento, transporte, importação ou exportação"
          ],
          "limites": [
            "não traz critérios de seleção de medidor nem requisitos de instalação física"
          ]
        },
        {
          "proposicao": "Os pontos de medição de transferência de custódia caracterizam transferência de propriedade entre vendedor e comprador e, segundo o trecho, devem seguir os mesmos requisitos técnicos da medição fiscal.",
          "trechos": [
            "E5f17fede420eb30f:688:1381"
          ],
          "condicoes": [
            "aplica-se a pontos de medição em condições contratuais de transferência de propriedade"
          ],
          "limites": [
            "a fonte não explicita quais são esses requisitos técnicos",
            "não especifica diferenças de projeto para offloading em FPSO"
          ]
        },
        {
          "proposicao": "Os pontos de medição da produção devem ser definidos no plano de desenvolvimento do campo, e os resultados de vazão precisam ser convertidos para condições e unidades de referência.",
          "trechos": [
            "E5f17fede420eb30f:688:1381",
            "E5f17fede420eb30f:1381:2081",
            "E5f17fede420eb30f:2081:2307"
          ],
          "condicoes": [
            "aplica-se à medição volumétrica do petróleo ou do gás natural produzido no campo"
          ],
          "limites": [
            "os valores numéricos das condições de referência estão apagados e não podem ser reconstruídos",
            "o trecho não informa como a conversão depende das propriedades dos fluidos nem dos instrumentos associados"
          ]
        }
      ]
    },
    {
      "id": "E259addf2c3a766df",
      "pertinente": true,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "As medições no setor de petróleo e gás são descritas como regidas por norma específica e classificadas em fiscal, fiscal compartilhada, apropriação, operacional e transferência de custódia.",
          "trechos": [
            "E259addf2c3a766df:0:694",
            "E259addf2c3a766df:694:1389",
            "E259addf2c3a766df:1389:2086"
          ],
          "condicoes": [
            "aplica-se às atividades de upstream e downstream segundo o trecho"
          ],
          "limites": [
            "o texto é descritivo e não reproduz o conteúdo normativo integral",
            "não fornece critérios técnicos de seleção e instalação do medidor"
          ]
        },
        {
          "proposicao": "A medição fiscal é associada ao ponto em que se caracteriza a transferência de propriedade do óleo da União para o concessionário.",
          "trechos": [
            "E259addf2c3a766df:694:1389"
          ],
          "condicoes": [
            "relacionada ao ponto de medição da produção definido na regulamentação citada no trecho"
          ],
          "limites": [
            "o trecho não cobre o detalhamento de projeto do ponto de medição"
          ]
        },
        {
          "proposicao": "A medição fiscal compartilhada é definida como a medição dos volumes de produção de dois ou mais campos que se misturam antes do ponto de medição; a medição para apropriação serve para repartir esses volumes por campo ou por poço.",
          "trechos": [
            "E259addf2c3a766df:1389:2086"
          ],
          "condicoes": [
            "mistura anterior ao ponto de medição para caracterizar medição fiscal compartilhada"
          ],
          "limites": [
            "não aborda como a arquitetura do sistema de medição deve ser selecionada ou instalada para viabilizar a apropriação"
          ]
        }
      ]
    },
