        {
          "proposicao": "O trecho reúne definições de medição fiscal compartilhada, medição operacional e medição para apropriação, reforçando a distinção funcional entre medição para controle, para repartição de produção e para medição conjunta de campos misturados.",
          "trechos": [
            "E311c50caa24e0fe6:0:696",
            "E311c50caa24e0fe6:696:1390"
          ],
          "condicoes": [
            "medição fiscal compartilhada depende da mistura de produção de dois ou mais campos antes do ponto de medição",
            "medição para apropriação aplica-se a campo com medição compartilhada ou a poços de um mesmo campo"
          ],
          "limites": [
            "não apresenta critérios de seleção do medidor nem requisitos de instalação"
          ]
        },
        {
          "proposicao": "Volume líquido é definido como o volume de petróleo em condições de referência descontado o volume de água e sedimentos.",
          "trechos": [
            "E311c50caa24e0fe6:696:1390"
          ],
          "condicoes": [
            "aplicado ao petróleo em condições de referência"
          ],
          "limites": [
            "o trecho não informa método de determinação de água e sedimentos nem instrumentos necessários"
          ]
        },
        {
          "proposicao": "O exemplo do campo de Carmópolis mostra coexistência de estações com medição operacional, fiscal e fiscal compartilhada, indicando consequências arquiteturais diferentes para a rede de medição do campo.",
          "trechos": [
            "E311c50caa24e0fe6:1390:2087",
            "E311c50caa24e0fe6:2087:2220"
          ],
          "condicoes": [
            "exemplo específico de um campo e suas estações"
          ],
          "limites": [
            "trata-se de configuração de instalação específica, não de requisito geral para FPSO/FSO",
            "não há descrição de condicionamento do escoamento, trechos retos ou limites de medidores"
          ]
        }
      ]
    }
